'use client'

import { useEffect, useMemo, useState } from 'react'

import { Select } from '@/components/form/select'
import {
  fetchStaffAppMembers,
  type HitPayStaffAppMember,
} from '#/lib/hitpay'
import { Field, FieldDescription, FieldLabel } from '@ui/field'

type StaffSelectLoad = () => Promise<{ members: HitPayStaffAppMember[] }>

type StaffSelectProps = {
  name: string
  label?: string | false
  description?: string
  placeholder?: string
  disabled?: boolean
  invalid?: boolean
  multiple?: boolean
  value?: string | string[] | null
  defaultValue?: string | string[] | null
  onValueChange?: (
    value: string | string[] | null,
    selected: HitPayStaffAppMember | HitPayStaffAppMember[] | null,
  ) => void
  roleTitles?: string[]
  locationId?: string
  load?: StaffSelectLoad
}

function staffLabel(member: HitPayStaffAppMember) {
  return member.name?.trim() || member.id
}

function filterMembers(
  members: HitPayStaffAppMember[],
  roleTitles?: string[],
  locationId?: string,
) {
  return members.filter((member) => {
    if (roleTitles && roleTitles.length > 0 && !roleTitles.includes(member.role?.title ?? '')) {
      return false
    }

    if (locationId && !member.locations.some((location) => location.id === locationId)) {
      return false
    }

    return true
  })
}

function pickMembers(members: HitPayStaffAppMember[], value: string | string[] | null) {
  if (value == null) {
    return null
  }

  if (Array.isArray(value)) {
    return members.filter((member) => value.includes(member.id))
  }

  return members.find((member) => member.id === value) ?? null
}

function StaffSelect({
  name,
  label = 'Staff',
  description,
  placeholder = 'Select staff',
  disabled,
  invalid,
  multiple = false,
  value,
  defaultValue,
  onValueChange,
  roleTitles,
  locationId,
  load = fetchStaffAppMembers,
}: StaffSelectProps) {
  const [members, setMembers] = useState<HitPayStaffAppMember[]>([])
  const [loading, setLoading] = useState(true)
  const roleKey = roleTitles?.join('\0') ?? ''

  useEffect(() => {
    let cancelled = false

    setLoading(true)
    load()
      .then((payload) => {
        if (!cancelled) {
          setMembers(filterMembers(payload.members, roleTitles, locationId))
        }
      })
      .catch(() => {
        if (!cancelled) {
          setMembers([])
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false)
        }
      })

    return () => {
      cancelled = true
    }
  }, [load, locationId, roleKey])

  const options = useMemo(
    () => members.map((member) => ({ value: member.id, label: staffLabel(member) })),
    [members],
  )

  const hidden = value == null ? '' : Array.isArray(value) ? value.join(',') : value
  const select = (
    <>
      <input type="hidden" name={name} value={hidden} />
      <Select
        id={name}
        searchable
        multiple={multiple}
        options={options}
        value={value === undefined ? undefined : (value as string | string[])}
        defaultValue={defaultValue === undefined ? undefined : (defaultValue as string | string[])}
        placeholder={loading ? 'Loading…' : placeholder}
        empty="No staff in this app."
        disabled={disabled || loading}
        invalid={invalid}
        onValueChange={(next) => onValueChange?.(next, pickMembers(members, next))}
      />
    </>
  )

  if (label === false) {
    return select
  }

  return (
    <Field data-invalid={invalid || undefined}>
      <FieldLabel htmlFor={name}>{label}</FieldLabel>
      {select}
      {description ? <FieldDescription>{description}</FieldDescription> : null}
    </Field>
  )
}

export { StaffSelect }
export type { StaffSelectLoad, StaffSelectProps }

import { useEffect, useState } from 'react'
import { studioAppId } from '#/lib/studio-app-id'

export {
  HITPAY_ALL_ROLES,
  HITPAY_MANAGER_ROLES,
  HITPAY_ROLE,
} from '#/lib/hitpay-roles'
export type { HitPayRoleTitle } from '#/lib/hitpay-roles'

export type HitPayRole = {
  id: string
  title: string
}

export type HitPayUser = {
  id: string
  email: string
  name: string | null
  role: HitPayRole | null
}

export type HitPayStaffLocation = {
  id: string
  name: string | null
}

export type HitPayStaffAppMember = {
  id: string
  email: string | null
  name: string | null
  role_id: string | null
  role: HitPayRole | null
  locations: HitPayStaffLocation[]
}

function assertBrowser(): void {
  if (typeof window === 'undefined') {
    throw new Error(
      'useHitPayUser and fetch* are browser-only. In createServerFn import getHitPaySession from #/lib/server/hitpay.',
    )
  }
}

function appStudioApi(path: '/user/info' | '/roles' | '/staff-app-members'): string {
  return `/api/apps/${encodeURIComponent(studioAppId())}${path}`
}

async function hitpayGet<T>(path: '/user/info' | '/roles' | '/staff-app-members'): Promise<T> {
  assertBrowser()

  const response = await fetch(appStudioApi(path), {
    credentials: 'include',
    headers: { accept: 'application/json' },
  })

  if (response.status === 401) {
    throw new Error('Sign in to HitPay to use this app.')
  }

  if (response.status >= 500) {
    throw new Error('HitPay is temporarily unavailable. Try again shortly.')
  }

  if (!response.ok) {
    throw new Error('You do not have access to this app.')
  }

  return (await response.json()) as T
}

export const fetchUserInfo = () => hitpayGet<HitPayUser>('/user/info')

export const fetchAppRoles = () => hitpayGet<{ roles: HitPayRole[] }>('/roles')

export const fetchStaffAppMembers = () =>
  hitpayGet<{ members: HitPayStaffAppMember[] }>('/staff-app-members')

/** Who is signed in. Browser only. Gate UI with `user.role.title`. */
export function useHitPayUser(): {
  user: HitPayUser | null
  error: string | null
  loading: boolean
  retry: () => void
} {
  const [user, setUser] = useState<HitPayUser | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const [attempt, setAttempt] = useState(0)

  useEffect(() => {
    let cancelled = false

    setLoading(true)
    setError(null)

    fetchUserInfo()
      .then((next) => {
        if (!cancelled) {
          setUser(next)
        }
      })
      .catch((caught) => {
        if (!cancelled) {
          setUser(null)
          setError(caught instanceof Error ? caught.message : 'Failed to load user.')
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false)
        }
      })

    return () => {
      cancelled = true
    }
  }, [attempt])

  return { user, error, loading, retry: () => setAttempt((value) => value + 1) }
}

/** Shared app-studio origin. Prefix every localStorage/sessionStorage key with this app id. */
export function studioAppId(): string {
  if (typeof window !== 'undefined') {
    const fromPath = window.location.pathname.split('/').filter(Boolean)[0]

    if (fromPath && fromPath !== 'api') return fromPath
  }

  const fromEnv =
    (typeof process !== 'undefined' ? process.env.APP_STUDIO_APP_ID : undefined)?.trim() ||
    String(import.meta.env.APP_STUDIO_APP_ID ?? '').trim()

  return fromEnv || 'local'
}

export function studioStorageKey(suffix: string): string {
  const part = suffix.replace(/^:+/, '')

  if (!part) {
    throw new Error('Storage key suffix is required.')
  }

  return `app-studio:${studioAppId()}:${part}`
}
